/** [longitude, latitude] -> [x, y] in the map's viewBox. */
export function projectToMap([lon, lat]) {
  const { minLon, maxLat, squeeze, scale } = VA_MAP.projection;
  return [(lon - minLon) * squeeze * scale, (maxLat - lat) * scale];
}
